#!/bin/sh
# Render the manual to PDF with headless Chrome: English, and Chinese (generated by make_zh.py).
cd "$(dirname "$0")" || exit 1
python3 make_zh.py
for pair in "manual.html:G1_Joint_Motor_Protocol_Guide.pdf" "manual_zh.html:G1_Joint_Motor_Protocol_Guide_zh.pdf"; do
  src=${pair%%:*}; out=${pair##*:}
  google-chrome-stable --headless --disable-gpu --no-pdf-header-footer --print-to-pdf="../$out" "file://$PWD/$src" 2>/dev/null
  printf "%s: " "$out"; pdfinfo "../$out" | grep Pages
done
